package com.retail.inventory.controller; import com.retail.inventory.dto.*; import com.retail.inventory.dto.request.*; import com.retail.inventory.dto.response.*; import com.retail.inventory.entity.enums.OrderStatus; import com.retail.inventory.service.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/v1/orders") @RequiredArgsConstructor public class OrderController {private final OrderService service;
 @GetMapping public ResponseEntity<ApiResponse<Page<OrderResponse>>> all(@RequestParam(required=false)String query,@RequestParam(required=false)OrderStatus status,@RequestParam(required=false)LocalDate fromDate,@RequestParam(required=false)LocalDate toDate,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return ResponseEntity.ok(ApiResponse.ok(service.findAll(query,status,fromDate,toDate,p)));}
 @GetMapping("/{id}") public ResponseEntity<ApiResponse<OrderResponse>> get(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok(service.findById(id)));}
 @PostMapping public ResponseEntity<ApiResponse<OrderResponse>> create(@Valid @RequestBody CreateOrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.create(r),"Order created"));}
 @PutMapping("/{id}/status") public ResponseEntity<ApiResponse<OrderResponse>> status(@PathVariable Long id,@Valid @RequestBody OrderStatusUpdateRequest r){return ResponseEntity.ok(ApiResponse.ok(service.updateStatus(id,r),"Order status updated"));}
 @PostMapping("/{id}/cancel") public ResponseEntity<ApiResponse<OrderResponse>> cancel(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok(service.cancel(id),"Order cancelled"));}
 @GetMapping("/{id}/items") public ResponseEntity<ApiResponse<List<OrderItemResponse>>> items(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.ok(service.items(id)));}}
